(()=>{const root=document.querySelector('[data-owned-catalogue]');if(!root)return;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let items=[],page=1;const params=new URLSearchParams(location.search),search=root.querySelector('#owned-search');search.value=params.get('q')||'';page=Math.max(1,parseInt(params.get('page'))||1);const grid=root.querySelector('[data-owned-results]'),count=root.querySelector('[data-owned-count]'),pagination=root.querySelector('[data-owned-pagination]');
function render(){const q=search.value.trim().toLowerCase();let found=items.filter(p=>(!root.dataset.ownedCategory||p.category===root.dataset.ownedCategory)&&(!q||[p.sku,p.name,p.contents,p.categoryName].join(' ').toLowerCase().includes(q)));if(root.querySelector('[data-owned-sort]').value==='sku')found.sort((a,b)=>a.sku.localeCompare(b.sku));const pages=Math.max(1,Math.ceil(found.length/24));page=Math.min(page,pages);count.textContent=found.length.toLocaleString('th-TH')+' แบบ · หน้า '+page+' / '+pages;grid.innerHTML=found.slice((page-1)*24,page*24).map(p=>`<article class="product-card owned-set-card"><a class="product-photo owned-photo" href="${p.url}">${p.image?`<img src="${p.image}" alt="${esc(p.name)}" loading="lazy" width="600" height="600">`:'<span class="missing-photo">ติดต่อขอภาพสินค้ารุ่นนี้</span>'}</a><div class="product-body"><span class="sku">${esc(p.sku)} · ขั้นต่ำ 10 ชุด</span><h3><a href="${p.url}">${esc(p.name)}</a></h3><p class="set-contents">${esc(p.contents)}</p><div class="product-actions"><a href="${p.url}">ดูของในชุด ↗</a><a href="/smartgift/contact?product=${encodeURIComponent(p.sku)}&sets=10">ขอราคา</a></div></div></article>`).join('')||'<div class="empty-state">ไม่พบชุดที่ตรงกับคำค้น ลองค้นด้วยรหัสรุ่นหรือชื่อของในชุด</div>';pagination.innerHTML=pages>1?`<button data-page="${page-1}" ${page===1?'disabled':''}>← ก่อนหน้า</button><span>${page} / ${pages}</span><button data-page="${page+1}" ${page===pages?'disabled':''}>ถัดไป →</button>`:'';const url=new URL(location.href);q?url.searchParams.set('q',search.value.trim()):url.searchParams.delete('q');page>1?url.searchParams.set('page',page):url.searchParams.delete('page');history.replaceState(null,'',url);}
root.querySelector('[data-owned-search]').onsubmit=e=>{e.preventDefault();page=1;render()};root.querySelector('[data-owned-sort]').onchange=()=>{page=1;render()};pagination.onclick=e=>{const button=e.target.closest('[data-page]');if(button&&!button.disabled){page=Number(button.dataset.page);render();count.scrollIntoView({block:'center',behavior:'smooth'})}};fetch('/data/owned-giftsets.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{items=data.items;render()}).catch(()=>{count.textContent='โหลดรายการเพิ่มเติมไม่สำเร็จ กรุณารีเฟรชหน้า';});})();
